1: /**
2:  * Pure tri-state overlay math for project-scoped capability control.
3:  *
4:  * The overlay is NOT a second denylist. It layers over a global baseline:
5:  *   - "on"      → force enabled (even if globally disabled)
6:  *   - "off"     → force disabled (even if globally enabled)
7:  *   - "inherit" → take the global baseline (we never persist this literal;
8:  *                 absence of a key === inherit)
9:  * Unknown/garbage values are treated as inherit so a bad config never makes
10:  * every capability vanish (spec §9).
11:  *
12:  * See docs/superpowers/specs/2026-06-01-project-scoped-capabilities-and-session-isolation-design.md
13:  */
14: import type { CapabilityOverride, CapabilityOverrides } from "../settings/schema.js";
15: import type { SettingsManager } from "../settings/manager.js";
16: import type { CapabilityDescriptor } from "./types.js";
17: 
18: /** Buckets in capabilityOverrides. */
19: export type OverrideBucket = keyof NonNullable<CapabilityOverrides>;
20: 
21: /** Apply a tri-state override to a baseline. inherit/garbage → baseline. */
22: export function applyOverride(globalEnabled: boolean, override?: CapabilityOverride): boolean {
23:   if (override === "on") return true;
24:   if (override === "off") return false;
25:   return globalEnabled;
26: }
27: 
28: /** Which capabilityOverrides bucket a descriptor kind writes to. */
29: export function bucketForKind(
30:   kind: CapabilityDescriptor["kind"] | "agent",
31: ): OverrideBucket | undefined {
32:   switch (kind) {
33:     case "skill":
34:       return "skills";
35:     case "plugin":
36:       return "plugins";
37:     case "mcp":
38:       return "mcp";
39:     case "agent":
40:       return "agents";
41:     case "builtin":
42:       return "builtin";
43:     default:
44:       return undefined;
45:   }
46: }
47: 
48: /** Strip the leading "<kind>:" prefix from a capability id to get its token. */
49: export function overrideTokenForId(id: string): string {
50:   const colon = id.indexOf(":");
51:   return colon >= 0 ? id.slice(colon + 1) : id;
52: }
53: 
54: /** Read the project override for a descriptor, normalizing inherit/garbage to undefined. */
55: export function overrideFor(
56:   overrides: CapabilityOverrides | undefined,
57:   kind: CapabilityDescriptor["kind"] | "agent",
58:   token: string,
59: ): "on" | "off" | undefined {
60:   const bucket = bucketForKind(kind);
61:   if (!bucket || !overrides) return undefined;
62:   const v = overrides[bucket]?.[token];
63:   return v === "on" || v === "off" ? v : undefined;
64: }
65: 
66: /**
67:  * Fold a project override bucket into a global "disabled" list, producing the
68:  * effective disabled list for run-time skill/plugin filtering. "on" un-disables
69:  * (removes from the list), "off" disables (adds to the list); inherit/absent
70:  * leaves the baseline.
71:  */
72: export function effectiveDisabledList(
73:   globalDisabled: string[],
74:   bucket: Record<string, CapabilityOverride> | undefined,
75: ): string[] {
76:   const disabled = new Set(globalDisabled);
77:   if (bucket) {
78:     for (const [token, state] of Object.entries(bucket)) {
79:       if (state === "on") disabled.delete(token);
80:       else if (state === "off") disabled.add(token);
81:     }
82:   }
83:   return [...disabled];
84: }
85: 
86: /**
87:  * Whitelist (opt-in) variant of {@link effectiveDisabledList}, used only for
88:  * the no-repo "conversation" scope where skill/plugin default-state is INVERTED:
89:  * everything is disabled UNLESS the project override bucket explicitly marks it
90:  * `"on"`. This is the opposite of the normal denylist (default-enabled) model.
91:  *
92:  * Given the full set of installed names and an override bucket:
93:  *   - a name explicitly `"on"`  → kept enabled (NOT in the returned list)
94:  *   - everything else (`"off"`, inherit/absent, garbage) → disabled (in the list)
95:  *
96:  * The returned list is the effective disabled list to feed run-time
97:  * skill/plugin filtering. Order follows `allInstalledNames`; duplicates are
98:  * collapsed.
99:  */
100: export function whitelistDisabledList(
101:   allInstalledNames: string[],
102:   bucket: Record<string, CapabilityOverride> | undefined,
103: ): string[] {
104:   const disabled: string[] = [];
105:   const seen = new Set<string>();
106:   for (const name of allInstalledNames) {
107:     if (seen.has(name)) continue;
108:     seen.add(name);
109:     if (bucket?.[name] === "on") continue; // explicit allow → stays enabled
110:     disabled.push(name);
111:   }
112:   return disabled;
113: }
114: 
115: /**
116:  * Fold a project builtin override bucket into the global enabled/disabled
117:  * builtin-tool lists, producing the lists to feed resolveBuiltinToolNames
118:  * (whose effective set is `preset.builtinTools ∪ enabled − disabled`).
119:  *
120:  * Unlike skills/plugins/agents — which the engine reads as a single denylist
121:  * — builtin tools resolve from a pair of allow/deny lists, so an override must
122:  * land in BOTH to win regardless of which side the preset/global config put
123:  * the token on:
124:  *   - "on"  → add to enabled, remove from disabled (force-enabled)
125:  *   - "off" → add to disabled, remove from enabled (force-disabled)
126:  *   - inherit/absent → leave the baseline untouched
127:  */
128: export function effectiveBuiltinLists(
129:   globalEnabled: string[],
130:   globalDisabled: string[],
131:   bucket: Record<string, CapabilityOverride> | undefined,
132: ): { enabledBuiltinTools: string[]; disabledBuiltinTools: string[] } {
133:   const enabled = new Set(globalEnabled);
134:   const disabled = new Set(globalDisabled);
135:   if (bucket) {
136:     for (const [token, state] of Object.entries(bucket)) {
137:       if (state === "on") {
138:         enabled.add(token);
139:         disabled.delete(token);
140:       } else if (state === "off") {
141:         disabled.add(token);
142:         enabled.delete(token);
143:       }
144:     }
145:   }
146:   return {
147:     enabledBuiltinTools: [...enabled],
148:     disabledBuiltinTools: [...disabled],
149:   };
150: }
151: 
152: const PROFILE_MERGED_OVERRIDE_BUCKETS = [
153:   "skills",
154:   "plugins",
155:   "agents",
156:   "mcp",
157:   "builtin",
158:   "pluginHooks",
159: ] as const;
160: 
161: /**
162:  * 合并两层三态 overlay：`top`（用户手写 capabilityOverrides）按 key 赢过
163:  * `base`（profile.overrides 快照）。Pet visibility 属于 host/project 策略，
164:  * 不可由 portable profile 注入；只保留 top 的直接项目设置。
165:  */
166: export function mergeCapabilityOverrides(
167:   base: CapabilityOverrides | undefined,
168:   top: CapabilityOverrides | undefined,
169: ): CapabilityOverrides | undefined {
170:   const merged: NonNullable<CapabilityOverrides> = {};
171:   for (const bucket of PROFILE_MERGED_OVERRIDE_BUCKETS) {
172:     const combined = { ...(base?.[bucket] ?? {}), ...(top?.[bucket] ?? {}) };
173:     if (Object.keys(combined).length > 0) merged[bucket] = combined;
174:   }
175:   if (top?.pet && Object.keys(top.pet).length > 0) merged.pet = { ...top.pet };
176:   return Object.keys(merged).length > 0 ? merged : undefined;
177: }
178: 
179: /**
180:  * 项目 overrides 的唯一读取咽喉：profile 快照垫底、项目设置覆盖、本地设置优先。
181:  * 所有折叠消费方（engine / disabled-lists / capability service）必须
182:  * 经这里读，不得再直接 getForScope().capabilityOverrides。
183:  */
184: export function effectiveProjectOverrides(
185:   settings: Pick<SettingsManager, "getForScope">,
186:   cwd: string | undefined,
187:   explicitProfileOverrides?: CapabilityOverrides,
188: ): CapabilityOverrides | undefined {
189:   if (!cwd) return undefined;
190:   try {
191:     const scoped = settings.getForScope("project", cwd) as {
192:       capabilityOverrides?: CapabilityOverrides;
193:       profile?: { overrides?: CapabilityOverrides };
194:     };
195:     const local = settings.getForScope("local", cwd) as {
196:       capabilityOverrides?: CapabilityOverrides;
197:     };
198:     // Both project layers are direct settings, unlike portable profile
199:     // overrides. Preserve their host visibility keys while merging per token.
200:     const direct = mergeCapabilityOverrides(scoped.capabilityOverrides, {
201:       ...local.capabilityOverrides,
202:       pet: {
203:         ...scoped.capabilityOverrides?.pet,
204:         ...local.capabilityOverrides?.pet,
205:       },
206:     });
207:     return mergeCapabilityOverrides(explicitProfileOverrides ?? scoped.profile?.overrides, direct);
208:   } catch {
209:     return undefined;
210:   }
211: }

1: /**
2:  * Pure projection functions: each turns one loader's output + the relevant
3:  * slice of current settings into CapabilityDescriptor[]. No I/O, no state —
4:  * the CapabilityService feeds them and composes the results.
5:  *
6:  * See docs/superpowers/specs/2026-05-29-capability-control-design.md
7:  */
8: 
9: import type { RegisteredTool, MCPServerConfig } from "../types.js";
10: import type { SkillDefinition } from "../skills/scanner.js";
11: import type { AgentDefinition } from "../agent/agent-definition.js";
12: import type { CapabilityDescriptor } from "./types.js";
13: 
14: /**
15:  * Builtin tools. A tool's switch lives in the denylist when it ships in the
16:  * preset default set (turning it off = adding to agent.disabledBuiltinTools),
17:  * and in the allowlist otherwise (turning it on = adding to
18:  * agent.enabledBuiltinTools). This mirrors resolveBuiltinToolNames, whose
19:  * effective set is `preset.builtinTools ∪ enabled − disabled`.
20:  */
21: export function projectBuiltin(input: {
22:   tools: RegisteredTool[];
23:   presetDefaults: string[];
24:   effective: string[];
25: }): CapabilityDescriptor[] {
26:   const defaults = new Set(input.presetDefaults);
27:   const on = new Set(input.effective);
28:   return input.tools.map((t) => {
29:     const inPreset = defaults.has(t.name);
30:     return {
31:       id: `builtin:${t.name}`,
32:       kind: "builtin" as const,
33:       name: t.name,
34:       description: t.description,
35:       enabled: on.has(t.name),
36:       control: inPreset
37:         ? {
38:             settingsKey: "agent.disabledBuiltinTools" as const,
39:             mode: "denylist" as const,
40:             token: t.name,
41:           }
42:         : {
43:             settingsKey: "agent.enabledBuiltinTools" as const,
44:             mode: "allowlist" as const,
45:             token: t.name,
46:           },
47:       origin: { isReadOnly: t.isReadOnly },
48:     };
49:   });
50: }
51: 
52: /**
53:  * MCP, projected per server (not per tool). Every configured server gets a
54:  * descriptor — including unconnected ones — driven by the mcpServers config;
55:  * tool counts come from the registry's connected mcp tools (0 if none).
56:  */
57: export function projectMcp(input: {
58:   mcpServers: Record<string, MCPServerConfig>;
59:   mcpTools: RegisteredTool[];
60: }): CapabilityDescriptor[] {
61:   const counts = new Map<string, number>();
62:   for (const t of input.mcpTools) {
63:     if (t.source !== "mcp" || !t.serverName) continue;
64:     counts.set(t.serverName, (counts.get(t.serverName) ?? 0) + 1);
65:   }
66:   return Object.entries(input.mcpServers).map(([serverName, cfg]) => {
67:     const toolCount = counts.get(serverName) ?? 0;
68:     return {
69:       id: `mcp:${serverName}`,
70:       kind: "mcp" as const,
71:       name: serverName,
72:       description: `${toolCount} tools`,
73:       enabled: cfg.enabled !== false,
74:       control: {
75:         settingsKey: "mcpServers" as const,
76:         mode: "record-flag" as const,
77:         token: serverName,
78:       },
79:       origin: { serverName, toolCount },
80:     };
81:   });
82: }
83: 
84: /**
85:  * Project/user skills. The caller MUST pass the FULL skill set (scanSkills
86:  * with empty opts), because scanSkills filters disabled entries out — passing
87:  * a filtered set would drop disabled skills from the list, leaving the UI no
88:  * way to re-enable them. Plugin-sourced skills are excluded here; they surface
89:  * under their plugin via projectPlugins.
90:  */
91: export function projectSkills(input: {
92:   skills: SkillDefinition[];
93:   disabledSkills: string[];
94: }): CapabilityDescriptor[] {
95:   const disabled = new Set(input.disabledSkills);
96:   return input.skills
97:     .filter((s) => s.source === "project" || s.source === "user")
98:     .map((s) => ({
99:       id: `skill:${s.name}`,
100:       kind: "skill" as const,
101:       name: s.name,
102:       description: s.description,
103:       enabled: !disabled.has(s.name),
104:       control: {
105:         settingsKey: "disabledSkills" as const,
106:         mode: "denylist" as const,
107:         token: s.name,
108:       },
109:       origin: { filePath: s.filePath },
110:     }));
111: }
112: 
113: /**
114:  * Project/user sub-agent roles, projected per role. Like projectSkills, the
115:  * caller MUST pass the FULL agent set (loaded WITHOUT the disabled filter), so
116:  * disabled roles still appear in the list and can be re-enabled. Plugin-sourced
117:  * agents are excluded — they ride their plugin's switch via projectPlugins, and
118:  * disabledAgents only governs user/project roles. Toggling writes the top-level
119:  * `disabledAgents` denylist (same key the 子代理 tab uses), so the two stay in
120:  * sync; the project overlay layers on via capabilityOverrides.agents.
121:  */
122: export function projectAgents(input: {
123:   agents: AgentDefinition[];
124:   disabledAgents: string[];
125: }): CapabilityDescriptor[] {
126:   const disabled = new Set(input.disabledAgents);
127:   return input.agents
128:     .filter((a) => a.source === "project" || a.source === "user")
129:     .map((a) => ({
130:       id: `agent:${a.name}`,
131:       kind: "agent" as const,
132:       name: a.name,
133:       description: a.description,
134:       enabled: !disabled.has(a.name),
135:       control: {
136:         settingsKey: "disabledAgents" as const,
137:         mode: "denylist" as const,
138:         token: a.name,
139:       },
140:       origin: { filePath: a.filePath },
141:     }));
142: }
143: 
144: /**
145:  * Installed plugins, projected per plugin. Install keys are `<plugin>@<market>`;
146:  * the bare plugin name is the substring before the last `@` and matches the
147:  * `plugin:` prefix that disabledPlugins controls.
148:  */
149: export function projectPlugins(input: {
150:   installed: Record<string, unknown>;
151:   disabledPlugins: string[];
152: }): CapabilityDescriptor[] {
153:   const disabled = new Set(input.disabledPlugins);
154:   const names = new Set<string>();
155:   for (const key of Object.keys(input.installed)) {
156:     const at = key.lastIndexOf("@");
157:     names.add(at > 0 ? key.slice(0, at) : key);
158:   }
159:   return [...names].map((name) => ({
160:     id: `plugin:${name}`,
161:     kind: "plugin" as const,
162:     name,
163:     description: "",
164:     enabled: !disabled.has(name),
165:     control: {
166:       settingsKey: "disabledPlugins" as const,
167:       mode: "denylist" as const,
168:       token: name,
169:     },
170:     origin: { pluginName: name },
171:   }));
172: }

1: /**
2:  * CapabilityService — the single control-layer entry point.
3:  *
4:  *  - list(): composes the four projections into one CapabilityDescriptor[].
5:  *  - setEnabled(id, on): reads the target descriptor's inlined `control` and
6:  *    routes the write to the right settings key. It never branches on `kind`.
7:  *
8:  * Dependencies are injected (not imported) so the service is unit-testable
9:  * without touching disk: the engine / desktop wiring supplies the real
10:  * ToolRegistry, SettingsManager, and loaders.
11:  *
12:  * See docs/superpowers/specs/2026-05-29-capability-control-design.md
13:  */
14: 
15: import type { ToolRegistry } from "../tool-system/registry.js";
16: import type { SettingsManager } from "../settings/manager.js";
17: import type { SkillDefinition } from "../skills/scanner.js";
18: import type { AgentDefinition } from "../agent/agent-definition.js";
19: import type { InstalledPluginsV2 } from "../plugins/types.js";
20: import type { CapabilityDescriptor, WriteScope, CapabilityOverrideState } from "./types.js";
21: import { CapabilityNotFoundError } from "./types.js";
22: import {
23:   projectBuiltin,
24:   projectMcp,
25:   projectSkills,
26:   projectPlugins,
27:   projectAgents,
28: } from "./project.js";
29: import {
30:   applyOverride,
31:   bucketForKind,
32:   effectiveProjectOverrides,
33:   overrideTokenForId,
34:   overrideFor,
35: } from "./overlay.js";
36: import type { CapabilityOverrides } from "../settings/schema.js";
37: 
38: export interface CapabilityServiceDeps {
39:   registry: Pick<ToolRegistry, "listToolsDetailed">;
40:   settings: Pick<
41:     SettingsManager,
42:     "get" | "saveUserSetting" | "saveProjectSetting" | "deleteProjectSetting" | "getForScope"
43:   >;
44:   cwd: string;
45:   scanSkills: (
46:     cwd: string,
47:     opts?: { disabledSkills?: string[]; disabledPlugins?: string[] },
48:   ) => SkillDefinition[];
49:   /** Full agent role set for `cwd` (user + project), loaded WITHOUT the
50:    *  disabled filter so disabled roles still list and can be re-enabled. */
51:   scanAgents: (cwd: string) => AgentDefinition[];
52:   readInstalledPlugins: () => InstalledPluginsV2;
53:   resolveBuiltinToolNames: (o?: {
54:     preset?: string;
55:     host?: "desktop";
56:     enabledBuiltinTools?: string[];
57:     disabledBuiltinTools?: string[];
58:   }) => string[];
59:   builtinToolHost?: "desktop";
60: }
61: 
62: export class CapabilityService {
63:   constructor(private readonly deps: CapabilityServiceDeps) {}
64: 
65:   /**
66:    * List capability descriptors. With no `cwd` this is the user/global view
67:    * (enabled === global baseline). With a `cwd` it's that project's view:
68:    * each descriptor gains globalEnabled / projectOverride / effectiveSource
69:    * and `enabled` reflects the tri-state overlay (spec §6.1).
70:    */
71:   list(cwd?: string): CapabilityDescriptor[] {
72:     const s = this.deps.settings.get() as Record<string, any>;
73:     const agent = (s.agent ?? {}) as Record<string, any>;
74:     const tools = this.deps.registry.listToolsDetailed();
75:     const preset: string | undefined = agent.preset;
76:     const host = this.deps.builtinToolHost;
77: 
78:     const base: CapabilityDescriptor[] = [
79:       ...projectBuiltin({
80:         tools: tools.filter((t) => t.source === "builtin"),
81:         presetDefaults: this.deps.resolveBuiltinToolNames({ preset, host }),
82:         effective: this.deps.resolveBuiltinToolNames({
83:           preset,
84:           host,
85:           enabledBuiltinTools: agent.enabledBuiltinTools ?? [],
86:           disabledBuiltinTools: agent.disabledBuiltinTools ?? [],
87:         }),
88:       }),
89:       ...projectMcp({
90:         mcpServers: s.mcpServers ?? {},
91:         mcpTools: tools.filter((t) => t.source === "mcp"),
92:       }),
93:       ...projectSkills({
94:         skills: this.deps.scanSkills(this.deps.cwd, {}),
95:         disabledSkills: s.disabledSkills ?? [],
96:       }),
97:       ...projectPlugins({
98:         installed: this.deps.readInstalledPlugins().plugins,
99:         disabledPlugins: s.disabledPlugins ?? [],
100:       }),
101:       ...projectAgents({
102:         agents: this.deps.scanAgents(this.deps.cwd),
103:         disabledAgents: s.disabledAgents ?? [],
104:       }),
105:     ];
106: 
107:     const userOverrides: CapabilityOverrides | undefined = cwd
108:       ? (this.deps.settings.getForScope("project", cwd).capabilityOverrides as CapabilityOverrides)
109:       : undefined;
110:     const foldedOverrides = cwd ? effectiveProjectOverrides(this.deps.settings, cwd) : undefined;
111: 
112:     return base.map((d) => {
113:       const globalEnabled = d.enabled;
114:       const token = overrideTokenForId(d.id);
115:       const ov = cwd ? overrideFor(foldedOverrides, d.kind, token) : undefined;
116:       const userOverride = cwd ? overrideFor(userOverrides, d.kind, token) : undefined;
117:       const enabled = applyOverride(globalEnabled, ov);
118:       return {
119:         ...d,
120:         enabled,
121:         globalEnabled,
122:         projectOverride: userOverride,
123:         effectiveSource: ov ? "project" : cwd ? "default" : "user",
124:       } as CapabilityDescriptor;
125:     });
126:   }
127: 
128:   /**
129:    * Toggle a capability. Default scope is "user" (back-compat: old callers
130:    * pass no opts → global write, unchanged). scope:"project" maps on/off to a
131:    * tri-state override and writes capabilityOverrides (requires cwd).
132:    */
133:   setEnabled(id: string, on: boolean, opts?: { scope?: WriteScope; cwd?: string }): void {
134:     if (opts?.scope === "project") {
135:       this.setOverride(id, on ? "on" : "off", {
136:         scope: "project",
137:         cwd: opts.cwd ?? this.deps.cwd,
138:       });
139:       return;
140:     }
141:     this.writeUserScope(id, on);
142:   }
143: 
144:   /**
145:    * Write a project tri-state override. "inherit" deletes the key (we never
146:    * persist the literal). All capability kinds — including builtin, which
147:    * writes to capabilityOverrides.builtin.<token> — now support project
148:    * overrides; only a kind with no bucket (bucketForKind returns undefined)
149:    * is rejected.
150:    */
151:   setOverride(
152:     id: string,
153:     state: CapabilityOverrideState,
154:     opts: { scope: "project"; cwd: string },
155:   ): void {
156:     const descriptor = this.list().find((c) => c.id === id);
157:     if (!descriptor) throw new CapabilityNotFoundError(id);
158:     const bucket = bucketForKind(descriptor.kind);
159:     if (!bucket) throw new Error(`Capability kind '${descriptor.kind}' has no project override`);
160:     if (!opts.cwd) throw new Error("project override requires cwd");
161:     const token = overrideTokenForId(id);
162:     const path = `capabilityOverrides.${bucket}.${token}`;
163:     if (state === "inherit") this.deps.settings.deleteProjectSetting(path, opts.cwd);
164:     else this.deps.settings.saveProjectSetting(path, state, opts.cwd);
165:   }
166: 
167:   /** Existing global write path — unchanged behavior, refactored out of setEnabled. */
168:   private writeUserScope(id: string, on: boolean): void {
169:     const descriptor = this.list().find((c) => c.id === id);
170:     if (!descriptor) throw new CapabilityNotFoundError(id);
171:     const { settingsKey, mode, token } = descriptor.control;
172:     const s = this.deps.settings.get() as Record<string, any>;
173: 
174:     if (mode === "record-flag") {
175:       const servers = { ...(s.mcpServers ?? {}) };
176:       // Never conjure a server that was never configured.
177:       if (!servers[token]) return;
178:       servers[token] = { ...servers[token], enabled: on };
179:       this.deps.settings.saveUserSetting("mcpServers", servers);
180:       return;
181:     }
182: 
183:     const arr = new Set<string>(readArray(s, settingsKey));
184:     // denylist: present ⇒ OFF, so we want it present when turning off.
185:     const wantPresent = mode === "allowlist" ? on : !on;
186:     if (wantPresent) arr.add(token);
187:     else arr.delete(token);
188:     this.deps.settings.saveUserSetting(settingsKey, [...arr]);
189:   }
190: }
191: 
192: /** Read an array at a dotted settings path (e.g. agent.disabledBuiltinTools). */
193: function readArray(s: Record<string, any>, key: string): string[] {
194:   let cur: any = s;
195:   for (const part of key.split(".")) cur = cur?.[part];
196:   return Array.isArray(cur) ? cur : [];
